import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append("\n");
        }
        String[] arr = sb.toString().split("\n");
        int idx = 0;
        String[] ax = arr[idx++].split(" ");
        int v = Integer.parseInt(ax[0]);
        int e = Integer.parseInt(ax[1]);

        if (e == 0) {
            System.out.println(0);
            return;
        }
        if (v <= 6) {
            System.out.println(e);
        } else {
            Map<Integer, List<Integer>> m = new HashMap<>();

            for (int i = 1; i <= v; i++) {
                m.put(i, new ArrayList<>());
            }

            for (int i = 0; i < e; i++) {
                String[] edge = arr[idx++].split(" ");
                int a = Integer.parseInt(edge[0]);
                int b = Integer.parseInt(edge[1]);
                m.get(a).add(b);
                m.get(b).add(a);
            }

            boolean f = false;
            int noOfVertices = 20;
            for (int j = 1; j <= 7; j++) {
                List<Integer> a7 = m.get(j);
                for (int i = 1; i <= 7; i++) {
                    if (i == j) continue;
                    List<Integer> other = m.get(i);
                    List<Integer> x = new ArrayList<>();
                    for (Integer el : a7) {
                        if (other.contains(el)) {
                            x.add(el);
                        }
                    }
                    if (x.size() == 0) {
                        f = true;
                        break;
                    } else if (x.size() < noOfVertices) {
                        noOfVertices = x.size();
                    }
                }
                if (f) break;
            }
            if (f) {
                System.out.println(e);
            } else {
                System.out.println(e - noOfVertices);
            }
        }
    }
}
